      <style>
  /* Estilização Premium do Slider */
  #nat-hero-slider {
    border-radius: 0.75rem;
    overflow: hidden;
    box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.1);
    margin-bottom: 2rem;
  }

  .nat-slide-img {
    height: 450px; /* Altura do banner no Desktop */
    width: 100%;
    object-fit: cover; /* Garante que a foto não fique esticada */
  }

  /* Overlay degradê escuro para garantir que o texto branco seja lido em fotos claras */
  .nat-slide-overlay {
    position: absolute;
    top: 0; left: 0; width: 100%; height: 100%;
    background: linear-gradient(to bottom, rgba(0,0,0,0.1) 40%, rgba(0,0,0,0.8) 100%);
  }

  .nat-carousel-caption {
    position: absolute;
    bottom: 2rem;
    left: 5%;
    right: 5%;
    text-align: center;
    z-index: 10;
  }

  .nat-carousel-caption h3 {
    font-size: 2rem;
    font-weight: 800;
    text-shadow: 1px 1px 4px rgba(0,0,0,0.6);
    margin-bottom: 1rem;
    color: #ffffff;
  }

  /* Responsividade para celular */
  @media (max-width: 768px) {
    .nat-slide-img { height: 300px; }
    .nat-carousel-caption h3 { font-size: 1.35rem; }
    .nat-carousel-caption { bottom: 1rem; }
  }
</style>

<div id="nat-hero-slider" class="carousel slide" data-bs-ride="carousel" data-bs-interval="4000">
  <div class="carousel-indicators" id="slider-indicators"></div>

  <div class="carousel-inner" id="slider-inner">
    <div class="text-center py-5 bg-light">
      <div class="spinner-border text-success" role="status"></div>
      <p class="mt-2 text-muted">Carregando destaques...</p>
    </div>
  </div>

  <button class="carousel-control-prev" type="button" data-bs-target="#nat-hero-slider" data-bs-slide="prev">
    <span class="carousel-control-prev-icon" aria-hidden="true"></span>
    <span class="visually-hidden">Anterior</span>
  </button>
  <button class="carousel-control-next" type="button" data-bs-target="#nat-hero-slider" data-bs-slide="next">
    <span class="carousel-control-next-icon" aria-hidden="true"></span>
    <span class="visually-hidden">Próximo</span>
  </button>
</div>

<script>
  (function() {
    document.addEventListener("DOMContentLoaded", function() {
      // Endpoint para pegar os últimos 3 posts
      const feedUrl = '/feeds/posts/default?alt=json&max-results=3';

      fetch(feedUrl)
        .then(response => response.json())
        .then(data => {
          const entries = data.feed.entry || [];
          let innerHtml = '';
          let indicatorsHtml = '';

          if (entries.length > 0) {
            entries.forEach((entry, index) => {
              // Pega o Título
              const title = entry.title.$t;

              // Pega o Link
              let link = '';
              entry.link.forEach(l => { if(l.rel === 'alternate') link = l.href; });

              // Pega a Imagem e Força Alta Resolução Panorâmica (1200x500 crop)
              let imgUrl = entry.media$thumbnail ? entry.media$thumbnail.url : 'https://via.placeholder.com/1200x500.png?text=Sem+Imagem';
              imgUrl = imgUrl.replace(/\/s[0-9]+(\-c)?\//, '/w1200-h500-c/');

              const activeClass = index === 0 ? 'active' : '';

              // Monta as bolinhas indicadoras
              indicatorsHtml += `<button type="button" data-bs-target="#nat-hero-slider" data-bs-slide-to="${index}" class="${activeClass}" aria-current="${index === 0 ? 'true' : 'false'}"></button>`;

              // Monta o Card do Slide
              innerHtml += `
                <div class="carousel-item ${activeClass}">
                  <img src="${imgUrl}" class="d-block nat-slide-img" alt="${title}">
                  <div class="nat-slide-overlay"></div>
                  <div class="nat-carousel-caption">
                    <h3>${title}</h3>
                    <a href="${link}" class="btn btn-primary rounded-pill px-4 fw-bold" style="background-color: var(--nat-primary); border: none; color: #121212;">Ler Artigo</a>
                  </div>
                </div>
              `;
            });

            // Injeta no HTML
            document.getElementById('slider-indicators').innerHTML = indicatorsHtml;
            document.getElementById('slider-inner').innerHTML = innerHtml;
          }
        })
        .catch(err => {
          console.error('Erro ao carregar o Slider:', err);
          document.getElementById('nat-hero-slider').style.display = 'none';
        });
    });
  })();
</script>





















      <style>
  #nat-back-to-top {
    position: fixed;
    bottom: 30px;
    right: 30px;
    width: 50px;
    height: 50px;
    background-color: var(--nat-primary, #8FBC8F);
    color: #121212;
    border: none;
    border-radius: 50%; /* Deixa perfeitamente redondo */
    box-shadow: 0 4px 10px rgba(0,0,0,0.15);
    cursor: pointer;
    z-index: 1040;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;

    /* Animação de entrada e saída */
    opacity: 0;
    visibility: hidden;
    transform: translateY(20px); /* Fica levemente abaixado quando escondido */
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Classe que o JS vai injetar para mostrar o botão */
  #nat-back-to-top.show-btn {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }

  #nat-back-to-top:hover {
    background-color: #222222; /* Fica escuro ao passar o mouse */
    color: #ffffff;
    box-shadow: 0 6px 15px rgba(0,0,0,0.25);
    transform: translateY(-3px) scale(1.05); /* Efeito de elevação magnética */
  }

  /* Ajuste para não atrapalhar o banner de cookies no mobile */
  @media (max-width: 767px) {
    #nat-back-to-top {
      bottom: 20px;
      right: 20px;
      width: 45px;
      height: 45px;
      font-size: 1.2rem;
    }
  }
</style>

<button id="nat-back-to-top" aria-label="Voltar ao topo" title="Voltar ao topo">
  <i class="bi bi-arrow-up-short"></i>
</button>

<script>
  (function() {
    document.addEventListener("DOMContentLoaded", function() {
      var backToTopBtn = document.getElementById("nat-back-to-top");

      if (backToTopBtn) {
        // Função para monitorar o scroll da página
        window.addEventListener("scroll", function() {
          // Se descer mais de 300px, mostra o botão
          if (window.scrollY > 300) {
            backToTopBtn.classList.add("show-btn");
          } else {
            // Se voltar pro topo, esconde o botão
            backToTopBtn.classList.remove("show-btn");
          }
        });

        // Ação ao clicar no botão
        backToTopBtn.addEventListener("click", function() {
          window.scrollTo({
            top: 0,
            behavior: "smooth" // Deslizamento suave
          });
        });
      }
    });
  })();
</script>





















